#!/usr/bin/env python3
"""pharma/tdm_bayesian — auto-generated run.py (archetype=pharma).

第一版只实现 simulate 模式:从 stdin/args 拿 inputs,产合理合成数据 JSON。
真实现路径(simulate=False)留 stub:返回 not-implemented + 提示。

输入契约:
  stdin JSON,字段按 SKILL.md 的 inputs 段;simulate 默认 true。
  CLI 兜底:--simulate / 各位置参数。

输出:
  stdout JSON;失败时也写 JSON {"ok": false, "error": "..."} 而非裸 traceback。
"""
import json
import sys

ARCHETYPE = "pharma"
BRAIN = "pharma"
SKILL = "tdm_bayesian"

def simulate(payload):
    """auto-generated by regen_simulate.py — outputs schema 来自 SKILL.md."""
    import copy
    import random
    random.seed(int(payload.get("seed", 42)) if isinstance(payload, dict) else 42)
    out = copy.deepcopy({'skill_id': 'tdm_bayesian', 'n_compounds': 0, 'admet_csv': '', 'diagnostics': {'brain': 'pharma', 'archetype': 'pharma'}})
    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({
                "simulated": True,
                "archetype": ARCHETYPE,
                "brain": BRAIN,
                "skill": SKILL,
            })
        if "skill_id" in out and not out["skill_id"]:
            out["skill_id"] = SKILL
    return out

def real(payload):
    """治疗药物监测 Bayesian 个体化:基于群体 prior (CL, V) 和 individual observed concs 做 MAP 估计。"""
    import os as _os
    import tempfile as _tempfile
    import time as _time
    try:
        from brains._common.lib.run_tool import run_tool
    except ImportError:
        import sys as _sys
        _sys.path.insert(0, "/home/zkyd/data1/mzy/praxis2-brains")
        from _common.lib.run_tool import run_tool  # noqa: F401
    pop_cl = float(payload.get("pop_cl_l_per_h", 10))
    pop_v = float(payload.get("pop_v_l", 30))
    pop_cl_cv = float(payload.get("pop_cl_cv", 0.3))
    pop_v_cv = float(payload.get("pop_v_cv", 0.3))
    observed_times = payload.get("observed_times") or []
    observed_concs = payload.get("observed_concs") or []
    dose = float(payload.get("dose_mg", 100))
    sigma_obs = float(payload.get("observation_sigma", 0.2))
    diagnostics = {"brain": BRAIN, "skill": SKILL, "archetype": ARCHETYPE,
                   "pop_cl": pop_cl, "pop_v": pop_v}
    if _os.environ.get("PRAXIS_SKILL_DRY_HOST") == "1":
        return {"ok": True, "skill_id": SKILL, "n_compounds": 0, "admet_csv": "",
                "diagnostics": {**diagnostics, "dry": True}}
    if not observed_times or len(observed_times) != len(observed_concs):
        return {"ok": False, "error": "需要 observed_times + observed_concs 同长度",
                "diagnostics": diagnostics}
    script = (
        "import json, sys, numpy as np\n"
        "from scipy.optimize import minimize\n"
        f"pop_cl, pop_v, cl_cv, v_cv = {pop_cl}, {pop_v}, {pop_cl_cv}, {pop_v_cv}\n"
        f"t = np.array({observed_times!r}, dtype=float); c_obs = np.array({observed_concs!r}, dtype=float)\n"
        f"dose = {dose}; sigma = {sigma_obs}\n"
        "def neg_log_post(params):\n"
        "    cl, v = params\n"
        "    if cl <= 0 or v <= 0: return 1e10\n"
        "    ke = cl/v\n"
        "    c_pred = dose/v * np.exp(-ke*t)\n"
        "    ll = -0.5 * np.sum(((c_obs - c_pred)/sigma)**2)\n"
        "    prior = -0.5 * (((np.log(cl) - np.log(pop_cl))/cl_cv)**2 + ((np.log(v) - np.log(pop_v))/v_cv)**2)\n"
        "    return -(ll + prior)\n"
        "res = minimize(neg_log_post, [pop_cl, pop_v], method='Nelder-Mead')\n"
        "cl_map, v_map = res.x\n"
        "json.dump({'cl_individual': float(cl_map), 'v_individual': float(v_map),\n"
        "           'cl_shift_pct': float((cl_map-pop_cl)/pop_cl*100),\n"
        "           'v_shift_pct': float((v_map-pop_v)/pop_v*100)}, sys.stdout)\n"
    )
    t0 = _time.time()
    r = run_tool(["python3", "-c", script], timeout=60)
    diagnostics["subprocess"] = {"wall_sec": r.get("wall_sec"), "rc": r.get("returncode")}
    if not r["ok"]:
        return {"ok": False, "error": r.get("error", "tdm fit 失败"), "diagnostics": diagnostics}
    try:
        parsed = json.loads(r["stdout"])
    except json.JSONDecodeError as e:
        return {"ok": False, "error": f"stdout 解析失败: {e}", "diagnostics": diagnostics}
    return {"ok": True, "skill_id": SKILL,
            "n_compounds": 1, "admet_csv": "",
            **parsed, "runtime_sec": round(_time.time() - t0, 2),
            "diagnostics": diagnostics}

def main():
    # stdin 优先(SkillExecTool 走 stdin)
    payload = {}
    if not sys.stdin.isatty():
        try:
            payload = json.load(sys.stdin)
            if not isinstance(payload, dict):
                payload = {}
        except json.JSONDecodeError:
            payload = {}
    if not payload:
        # 简易 CLI 兜底
        import argparse
        ap = argparse.ArgumentParser()
        ap.add_argument("--simulate", action="store_true", default=True)
        ap.add_argument("--seed", type=int, default=42)
        args, _ = ap.parse_known_args()
        payload = {"simulate": args.simulate, "seed": args.seed}

    simulate_mode = bool(payload.get("simulate", True))
    try:
        out = simulate(payload) if simulate_mode else real(payload)
    except Exception as e:
        out = {"ok": False, "error": f"run.py 内部错误: {e!r}"}

    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({"archetype": ARCHETYPE, "brain": BRAIN, "skill": SKILL})
    json.dump(out, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return 0

if __name__ == "__main__":
    sys.exit(main())
